const {classify}=require('./classify.cjs');exports.resume=(q,id)=>q.map(x=>x.id===id&&x.state==='uncertain'?{...x,state:'ready'}:x);exports.drain=async(q,post,persist)=>{const next=[];let stopped=false;for(let i=0;i<q.length;i++){const item=q[i];if(item.state!=='ready'){next.push(item);continue;}if(stopped){next.push(item);continue;}try{await post(item);}catch(e){const outcome=classify(e);next.push({...item,state:outcome==='rejected'?'rejected':'uncertain'});if(outcome!=='rejected'){stopped=true;}continue;}}await persist(next);q.length=0;q.push(...next);return q;};